1	package com.example.starter.service;
2	
3	import com.example.starter.api.ApiException;
4	import com.example.starter.api.dto.MutationResponse;
5	import com.example.starter.api.dto.ReviewRequest;
6	import com.example.starter.api.dto.ReviewResultDto;
7	import com.example.starter.api.dto.RouteCreateRequest;
8	import com.example.starter.api.dto.RoutePointDto;
9	import com.example.starter.api.dto.RouteReplaceRequest;
10	import com.example.starter.api.dto.RouteResult;
11	import com.example.starter.api.dto.ZoneCreateRequest;
12	import com.example.starter.api.dto.ZoneResult;
13	import com.example.starter.api.dto.ZoneRevokeRequest;
14	import com.example.starter.domain.Geometry;
15	import com.example.starter.domain.Point;
16	import com.example.starter.domain.ReviewConclusion;
17	import com.example.starter.domain.ZoneStatus;
18	import com.example.starter.repo.AirspaceRepository;
19	import com.example.starter.repo.DedupPo;
20	import com.example.starter.repo.ReviewPo;
21	import com.example.starter.repo.ReviewRepository;
22	import com.example.starter.repo.RoutePo;
23	import com.example.starter.repo.RouteRepository;
24	import com.example.starter.repo.ZonePo;
25	import com.fasterxml.jackson.core.JsonProcessingException;
26	import com.fasterxml.jackson.databind.JsonNode;
27	import com.fasterxml.jackson.databind.ObjectMapper;
28	import com.fasterxml.jackson.databind.node.ArrayNode;
29	import com.fasterxml.jackson.databind.node.JsonNodeFactory;
30	import com.fasterxml.jackson.databind.node.ObjectNode;
31	import org.springframework.dao.DuplicateKeyException;
32	import org.springframework.http.HttpStatus;
33	import org.springframework.stereotype.Service;
34	import org.springframework.transaction.PlatformTransactionManager;
35	import org.springframework.transaction.support.TransactionTemplate;
36	
37	import java.nio.charset.StandardCharsets;
38	import java.security.MessageDigest;
39	import java.security.NoSuchAlgorithmException;
40	import java.time.Clock;
41	import java.util.ArrayList;
42	import java.util.HexFormat;
43	import java.util.List;
44	import java.util.Set;
45	import java.util.TreeSet;
46	import java.util.UUID;
47	import java.util.function.Supplier;
48	
49	/**
50	 * 禁飞区与航线审查业务服务。
51	 *
52	 * <p>所有写操作在同一数据库事务内完成业务变更与幂等去重记录的原子提交；
53	 * 失败（含业务冲突）回滚事务，不占用 requestId。</p>
54	 *
55	 * <p>审核事务先锁全局空域版本行、再锁航线行：区域变更事务必须更新版本行，
56	 * 因而与审核互斥，保证审核使用的空域版本号与全部禁飞区来自同一已提交状态，
57	 * 不会产生“携带新版本、使用旧区域”或反之的结论。</p>
58	 */
59	@Service
60	public class AirspaceReviewService {
61	
62	    static final String KIND_ZONE_CREATE = "ZONE_CREATE";
63	    static final String KIND_ZONE_REVOKE = "ZONE_REVOKE";
64	    static final String KIND_ROUTE_CREATE = "ROUTE_CREATE";
65	    static final String KIND_ROUTE_REPLACE = "ROUTE_REPLACE";
66	    static final String KIND_REVIEW = "REVIEW";
67	
68	    private final AirspaceRepository airspaceRepo;
69	    private final RouteRepository routeRepo;
70	    private final ReviewRepository reviewRepo;
71	    private final ObjectMapper objectMapper;
72	    private final Clock clock;
73	    private final TransactionTemplate txTemplate;
74	
75	    public AirspaceReviewService(AirspaceRepository airspaceRepo,
76	                                 RouteRepository routeRepo,
77	                                 ReviewRepository reviewRepo,
78	                                 ObjectMapper objectMapper,
79	                                 Clock clock,
80	                                 PlatformTransactionManager transactionManager) {
81	        this.airspaceRepo = airspaceRepo;
82	        this.routeRepo = routeRepo;
83	        this.reviewRepo = reviewRepo;
84	        this.objectMapper = objectMapper;
85	        this.clock = clock;
86	        this.txTemplate = new TransactionTemplate(transactionManager);
87	    }
88	
89	    // ============================ 禁飞区 ============================
90	
91	    /** 创建禁飞区；同键同参重放原结果，异参 409。 */
92	    public MutationResponse createZone(ZoneCreateRequest request) {
93	        return withIdempotency(request.requestId(), KIND_ZONE_CREATE, canonicalHash(request), () -> {
94	            if (request.xMin() >= request.xMax() || request.yMin() >= request.yMax()) {
95	                throw new ApiException(HttpStatus.BAD_REQUEST, "INVALID_ZONE_RECTANGLE",
96	                        "禁飞区必须是非退化轴对齐矩形：xMin < xMax 且 yMin < yMax");
97	            }
98	            if (airspaceRepo.findZone(request.zoneId()) != null) {
99	                throw new ApiException(HttpStatus.CONFLICT, "ZONE_ALREADY_EXISTS",
100	                        "禁飞区已存在: " + request.zoneId());
101	            }
102	            long newVersion = airspaceRepo.incrementGlobalVersion();
103	            airspaceRepo.insertZone(new ZonePo(request.zoneId(), request.xMin(), request.yMin(),
104	                    request.xMax(), request.yMax(), ZoneStatus.ACTIVE.name(), newVersion, null));
105	            return new MutationResponse(request.requestId(), false,
106	                    new ZoneResult(request.zoneId(), ZoneStatus.ACTIVE.name(), newVersion));
107	        });
108	    }
109	
110	    /** 撤销禁飞区（只能撤销一次，撤销使空域版本加一）。 */
111	    public MutationResponse revokeZone(ZoneRevokeRequest request) {
112	        return withIdempotency(request.requestId(), KIND_ZONE_REVOKE, canonicalHash(request), () -> {
113	            ZonePo zone = airspaceRepo.findZone(request.zoneId());
114	            if (zone == null) {
115	                throw new ApiException(HttpStatus.NOT_FOUND, "ZONE_NOT_FOUND",
116	                        "禁飞区不存在: " + request.zoneId());
117	            }
118	            if (ZoneStatus.REVOKED.name().equals(zone.status())) {
119	                throw new ApiException(HttpStatus.CONFLICT, "ZONE_ALREADY_REVOKED",
120	                        "禁飞区已撤销: " + request.zoneId());
121	            }
122	            long newVersion = airspaceRepo.incrementGlobalVersion();
123	            airspaceRepo.markRevoked(request.zoneId(), newVersion);
124	            return new MutationResponse(request.requestId(), false,
125	                    new ZoneResult(request.zoneId(), ZoneStatus.REVOKED.name(), newVersion));
126	        });
127	    }
128	
129	    // ============================ 航线 ============================
130	
131	    /** 创建航线（初始版本 1）。 */
132	    public MutationResponse createRoute(RouteCreateRequest request) {
133	        return withIdempotency(request.requestId(), KIND_ROUTE_CREATE, canonicalHash(request), () -> {
134	            List<Point> points = toPoints(request.points());
135	            validatePointsDistinct(points);
136	            if (routeRepo.findRoute(request.routeId()) != null) {
137	                throw new ApiException(HttpStatus.CONFLICT, "ROUTE_ALREADY_EXISTS",
138	                        "航线已存在: " + request.routeId());
139	            }
140	            routeRepo.insertRoute(request.routeId(), points);
141	            return new MutationResponse(request.requestId(), false,
142	                    new RouteResult(request.routeId(), 1));
143	        });
144	    }
145	
146	    /** 替换航线点列，expectedVersion 不匹配返回 409；成功版本加一。 */
147	    public MutationResponse replaceRoute(RouteReplaceRequest request) {
148	        return withIdempotency(request.requestId(), KIND_ROUTE_REPLACE, canonicalHash(request), () -> {
149	            List<Point> points = toPoints(request.points());
150	            validatePointsDistinct(points);
151	            RoutePo route = routeRepo.findRoute(request.routeId());
152	            if (route == null) {
153	                throw new ApiException(HttpStatus.NOT_FOUND, "ROUTE_NOT_FOUND",
154	                        "航线不存在: " + request.routeId());
155	            }
156	            if (route.version() != request.expectedVersion()) {
157	                throw new ApiException(HttpStatus.CONFLICT, "VERSION_CONFLICT",
158	                        "航线版本不匹配：expected=" + request.expectedVersion()
159	                                + ", current=" + route.version());
160	            }
161	            // 条件更新兜底并发替换：更新 0 行说明版本已被其他事务推进
162	            int updated = routeRepo.compareAndIncrementVersion(
163	                    request.routeId(), request.expectedVersion());
164	            if (updated == 0) {
165	                throw new ApiException(HttpStatus.CONFLICT, "VERSION_CONFLICT",
166	                        "航线版本已变化，请使用最新 expectedVersion 重试");
167	            }
168	            routeRepo.deletePoints(request.routeId());
169	            routeRepo.insertPoints(request.routeId(), points);
170	            return new MutationResponse(request.requestId(), false,
171	                    new RouteResult(request.routeId(), request.expectedVersion() + 1));
172	        });
173	    }
174	
175	    // ============================ 审核 ============================
176	
177	    /** 提交审核：任一指定版本不是当前版本返回 409；结果不可变。 */
178	    public MutationResponse review(ReviewRequest request) {
179	        return withIdempotency(request.requestId(), KIND_REVIEW, canonicalHash(request), () -> {
180	            // 先锁空域版本行：与任何区域创建/撤销事务互斥
181	            long globalVersion = airspaceRepo.getGlobalVersionForUpdate();
182	            // 再锁航线行：与航线替换事务互斥，保证版本号与点列一致
183	            RoutePo route = routeRepo.findRouteForUpdate(request.routeId());
184	            if (route == null) {
185	                throw new ApiException(HttpStatus.NOT_FOUND, "ROUTE_NOT_FOUND",
186	                        "航线不存在: " + request.routeId());
187	            }
188	            if (route.version() != request.routeVersion()) {
189	                throw new ApiException(HttpStatus.CONFLICT, "VERSION_CONFLICT",
190	                        "航线版本不是当前版本：submitted=" + request.routeVersion()
191	                                + ", current=" + route.version());
192	            }
193	            if (globalVersion != request.airspaceVersion()) {
194	                throw new ApiException(HttpStatus.CONFLICT, "VERSION_CONFLICT",
195	                        "空域版本不是当前版本：submitted=" + request.airspaceVersion()
196	                                + ", current=" + globalVersion);
197	            }
198	            // 持锁状态下读取全部有效禁飞区，与上面的版本号同属一个一致状态
199	            List<ZonePo> activeZones = airspaceRepo.findActiveZones();
200	            Set<String> hits = new TreeSet<>();
201	            for (ZonePo zone : activeZones) {
202	                if (Geometry.polylineHitsRectangle(route.points(),
203	                        zone.xMin(), zone.yMin(), zone.xMax(), zone.yMax())) {
204	                    hits.add(zone.zoneId());
205	                }
206	            }
207	            String conclusion = hits.isEmpty()
208	                    ? ReviewConclusion.CLEAR.name()
209	                    : ReviewConclusion.BLOCKED.name();
210	            String reviewId = "rv_" + UUID.randomUUID();
211	            ReviewPo po = new ReviewPo(reviewId, request.routeId(), route.version(), globalVersion,
212	                    conclusion, new ArrayList<>(hits), List.copyOf(route.points()),
213	                    request.requestId(), nowMillis());
214	            reviewRepo.insertReview(po);
215	            return new MutationResponse(request.requestId(), false, toDto(po, conclusion, true));
216	        });
217	    }
218	
219	    /** 按 reviewId 查询历史审核，保留原结论。 */
220	    public ReviewResultDto getReview(String reviewId) {
221	        ReviewPo po = reviewRepo.findReview(reviewId);
222	        if (po == null) {
223	            throw new ApiException(HttpStatus.NOT_FOUND, "REVIEW_NOT_FOUND",
224	                    "审核记录不存在: " + reviewId);
225	        }
226	        // 历史查询永远返回保存时的原结论，不重新计算
227	        return toDto(po, po.conclusion(), null);
228	    }
229	
230	    /** 查询某航线当前可用结论；任何相关版本不再匹配返回 STALE。 */
231	    public ReviewResultDto getCurrentReview(String routeId) {
232	        return txTemplate.execute(status -> {
233	            ReviewPo latest = reviewRepo.findLatestReview(routeId);
234	            if (latest == null) {
235	                throw new ApiException(HttpStatus.NOT_FOUND, "REVIEW_NOT_FOUND",
236	                        "该航线尚无审核记录: " + routeId);
237	            }
238	            RoutePo currentRoute = routeRepo.findRoute(routeId);
239	            long globalVersion = airspaceRepo.getGlobalVersion();
240	            boolean current = currentRoute != null
241	                    && currentRoute.version() == latest.routeVersion()
242	                    && globalVersion == latest.airspaceVersion();
243	            // 不匹配时绝不能把旧 CLEAR/BLOCKED 当成当前结论，统一返回 STALE
244	            String conclusion = current ? latest.conclusion() : "STALE";
245	            return toDto(latest, conclusion, current);
246	        });
247	    }
248	
249	    // ============================ 幂等与事务 ============================
250	
251	    /**
252	     * 在事务内执行幂等写操作：
253	     * 同键同参返回首次成功结果（标记 replayed=true）；同键异参/异种操作抛 409；
254	     * 业务异常回滚、不占用 requestId；去重记录与业务变更同一事务原子提交。
255	     *
256	     * <p>同键并发时，落败事务可能先撞上唯一约束（DuplicateKeyException），
257	     * 也可能在持锁后读到赢家已提交的状态而抛业务冲突（409）；两种情况都在
258	     * 回滚后用新事务查询去重表：赢家同键同参已提交则重放原结果，否则按原错误抛出。</p>
259	     */
260	    private MutationResponse withIdempotency(String requestId, String kind, String paramHash,
261	                                             Supplier<MutationResponse> action) {
262	        try {
263	            return txTemplate.execute(status -> doIdempotent(requestId, kind, paramHash, action));
264	        } catch (DuplicateKeyException dup) {
265	            return resolveAfterRace(requestId, kind, paramHash,
266	                    new ApiException(HttpStatus.CONFLICT, "RESOURCE_CONFLICT",
267	                            "并发资源冲突，请稍后使用相同 requestId 与参数重试"));
268	        } catch (ApiException api) {
269	            if (api.status() == HttpStatus.CONFLICT) {
270	                return resolveAfterRace(requestId, kind, paramHash, api);
271	            }
272	            throw api;
273	        }
274	    }
275	
276	    /**
277	     * 并发落败后的裁决：去重表中存在同键记录则按重放/异参冲突处理；
278	     * 不存在（说明该 requestId 尚未成功、这是一次真实业务冲突）则抛出原错误，
279	     * 不占用 requestId。
280	     */
281	    private MutationResponse resolveAfterRace(String requestId, String kind, String paramHash,
282	                                              ApiException original) {
283	        DedupPo winner = txTemplate.execute(status -> reviewRepo.findDedup(requestId));
284	        if (winner == null) {
285	            throw original;
286	        }
287	        ensureSameRequest(winner, kind, paramHash);
288	        return deserializeReplay(winner);
289	    }
290	
291	    private MutationResponse doIdempotent(String requestId, String kind, String paramHash,
292	                                          Supplier<MutationResponse> action) {
293	        DedupPo existing = reviewRepo.findDedup(requestId);
294	        if (existing != null) {
295	            ensureSameRequest(existing, kind, paramHash);
296	            return deserializeReplay(existing);
297	        }
298	        // 业务异常会触发事务回滚，去重键不会被占用
299	        MutationResponse result = action.get();
300	        reviewRepo.insertDedup(new DedupPo(requestId, kind, paramHash,
301	                writeJson(result), nowMillis()));
302	        return result;
303	    }
