312	    private MutationResponse deserializeReplay(DedupPo po) {
313	        try {
314	            MutationResponse original = objectMapper.readValue(po.responseJson(), MutationResponse.class);
315	            // 业务结果原样重放，仅传输标记告知客户端本次为重放
