59	                        + "hit_zone_ids, points_snapshot, request_id, created_at) "
60	                        + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
61	                po.reviewId(), po.routeId(), po.routeVersion(), po.airspaceVersion(),
62	                po.conclusion(), encodeZoneIds(po.hitZoneIds()), encodePoints(po.pointsSnapshot()),
63	                po.requestId(), po.createdAt());
