419	    @Test
420	    void concurrentZoneCreateAndReviewNeverMixesVersionsAndZones() throws Exception {
421	        int iterations = 12;
422	        ExecutorService pool = Executors.newFixedThreadPool(4);
423	        try {
424	            for (int i = 0; i < iterations; i++) {
425	                String routeId = "cr-" + i;
426	                String zoneId = "cz-" + i;
427	                // 每轮使用互不相交的 y 几何，避免历史轮次已提交区域命中本轮新航线
428	                int y = 10 + i * 100;
429	                service.createRoute(new RouteCreateRequest(
430	                        routeId, pts(0, y, 100, y), "req-" + rid("route")));
431	                long versionBefore = jdbc.queryForObject(
432	                        "SELECT global_version FROM airspace_meta WHERE id=1", Long.class);
433	
434	                CyclicBarrier barrier = new CyclicBarrier(2);
435	                // 审核方：明确提交建区前的空域版本
436	                Future<Object> reviewFuture = pool.submit(() -> {
437	                    barrier.await(5, TimeUnit.SECONDS);
438	                    try {
439	                        return service.review(new ReviewRequest(
440	                                routeId, 1, versionBefore, "req-review-" + routeId));
441	                    } catch (ApiException ex) {
442	                        return ex;
443	                    }
